code_sketch:
struct Money: Codable, Hashable {
    var amount: Decimal                 // base-10, ~38 significant digits
    var currency: Currency              // ISO 4217 identity with minor units
    func rounded(_ mode: Decimal.RoundingMode = .bankers) -> Money {
        var out = Decimal(), value = amount
        NSDecimalRound(&out, &value, currency.minorUnits, mode)
        return Money(amount: out, currency: currency)
    }
}
